import * as React from 'react';
import { expect, vi, it } from 'vitest';
import { createRenderer, fireEvent, screen } from '@mui/internal-test-utils';
import { Field } from '@base-ui/react/field';
const { render } = createRenderer();
it('controlled + preventDefault + setState', async () => {
  const validate = vi.fn(() => null);
  function App() {
    const [v, setV] = React.useState('');
    return (<Field.Root validationMode="onChange" validate={validate}><Field.Control value={v} onValueChange={setV} /></Field.Root>);
  }
  await render(<App />);
  const c = screen.getByRole('textbox');
  c.addEventListener('input', (e) => e.preventDefault(), { capture: true, once: true });
  fireEvent.input(c, { cancelable: true, target: { value: 'a' } });
  console.log('validate calls (controlled, prevented):', validate.mock.calls.length);
});
it('uncontrolled cancel dirty/filled', async () => {
