  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
  const r = screen.getByTestId('r');
  console.log('uncontrolled cancel dirty/filled:', r.hasAttribute('data-dirty'), r.hasAttribute('data-filled'));
});
EOF
